package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen0Test {

    @Test
    public void testEncodeBase64_NullInput() {
        byte[] input = null;
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        assertNull(result);
    }

    @Test
    public void testEncodeBase64_EmptyInput() {
        byte[] input = new byte[0];
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        assertEquals(0, result.length);
    }

    @Test
    public void testEncodeBase64_SizeExceeded() {
        byte[] input = new byte[100];
        // Set maxResultSize very small to trigger IllegalArgumentException
        int maxResultSize = 10;
        try {
            Base64.encodeBase64(input, false, false, maxResultSize);
            fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Input array too big"));
        }
    }

    @Test
    public void testEncodeBase64_StandardEncoding() {
        byte[] input = "Hello World".getBytes();
        // Sufficiently large maxResultSize
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        String expected = "SGVsbG8gV29ybGQ=";
        assertEquals(expected, new String(result));
    }

    @Test
    public void testEncodeBase64_UrlSafeEncoding() {
        byte[] input = new byte[]{(byte) 0xfb, (byte) 0xff, (byte) 0xbf}; 
        // Standard Base64 would use + and /
        // URL Safe uses - and _
        byte[] result = Base64.encodeBase64(input, false, true, 100);
        String resultStr = new String(result);
        assertFalse("Should not contain +", resultStr.contains("+"));
        assertFalse("Should not contain /", resultStr.contains("/"));
        // Validate it works with the URL safe logic
        assertEquals("-_-_", resultStr.replace("-", "-").replace("_", "_")); 
    }

    @Test
    public void testEncodeBase64_ChunkedEncoding() {
        byte[] input = "This is a long string to test chunking logic".getBytes();
        // isChunked = true
        // When chunked, the internal Base64 constructor uses MIME_CHUNK_SIZE and CHUNK_SEPARATOR
        byte[] result = Base64.encodeBase64(input, true, false, 1000);
        assertNotNull(result);
        assertTrue(result.length > 0);
    }

    @Test
    public void testEncodeBase64_ChunkedUrlSafe() {
        byte[] input = "Chunked and URL safe test string".getBytes();
        byte[] result = Base64.encodeBase64(input, true, true, 1000);
        assertNotNull(result);
        String resultStr = new String(result);
        assertFalse(resultStr.contains("+"));
        assertFalse(resultStr.contains("/"));
    }

    @Test
    public void testEncodeBase64_BoundarySize() {
        byte[] input = new byte[1];
        // Calculate a safe max size. Base64 length is roughly 4/3 of input.
        // For 1 byte, result is 4 bytes.
        int maxResultSize = 4; 
        byte[] result = Base64.encodeBase64(input, false, false, maxResultSize);
        assertNotNull(result);
    }
}
